import pytest
from review.out.astra_scratch.test_r16_attacks import daily

@pytest.mark.parametrize('market', ['TWSE', 'TPEX'])
def test_response_date_matches_requested_session(tmp_path, market):
    try:
        _, market_data = daily(tmp_path, market, days=('2024-01-05',), body_day='2024-01-12')
    except ValueError:
        return
    assert not market_data.securities

from datetime import date
from twlab.sources import twse_daily as td

def test_missing_columns_are_not_valid_market_data():
    try:
        bar = td.bars_twse(date(2024,1,5), [{'證券代號':'2330', '開盤價':'100', '收盤價':'100'}])['2330']
    except ValueError:
        return
    assert not bar.has_regular_price
